import java.text.Normalizer;
import java.util.EnumSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * A filter over the customer list, applied by the backend.
 *
 * <p>A customer matches when it satisfies both parts: every whitespace-separated
 * term in {@code name} must appear, case- and accent-insensitively, as a
 * substring of the customer's first name or last name; and, if {@code statuses}
 * is non-empty, the customer's status must be one of them.
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());

    private static final Pattern WHITESPACE = Pattern.compile("\\s+");

    public CustomerFilter {
        name = name == null ? "" : name;
        statuses = (statuses == null || statuses.isEmpty())
                ? Set.of()
                : java.util.Collections.unmodifiableSet(EnumSet.copyOf(statuses));
    }

    /** Whether the given customer satisfies both parts of this filter. */
    public boolean matches(Customer customer) {
        return matchesStatus(customer) && matchesName(customer);
    }

    private boolean matchesStatus(Customer customer) {
        return statuses.isEmpty() || statuses.contains(customer.status());
    }

    private boolean matchesName(Customer customer) {
        List<String> terms = nameTerms();
        if (terms.isEmpty()) {
            return true;
        }
        String firstName = normalize(customer.firstName());
        String lastName = normalize(customer.lastName());
        for (String term : terms) {
            if (!firstName.contains(term) && !lastName.contains(term)) {
                return false;
            }
        }
        return true;
    }

    private List<String> nameTerms() {
        String trimmed = name.trim();
        if (trimmed.isEmpty()) {
            return List.of();
        }
        return WHITESPACE.splitAsStream(trimmed).map(CustomerFilter::normalize).toList();
    }

    private static String normalize(String value) {
        String decomposed = Normalizer.normalize(value, Normalizer.Form.NFD);
        return decomposed.replaceAll("\\p{M}+", "").toLowerCase(Locale.ROOT);
    }
}
