@@ -0,0 +1,64 @@
+package com.example.customers.domain;
+
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.Set;
+
+import org.junit.jupiter.api.Test;
+
+class CustomerFilterTest {
+
+    private static final Customer AALTONEN = new Customer(
+            1, "Ada", "Aaltonen", "ada@example.com", "Finland", CustomerStatus.ACTIVE);
+    private static final Customer MAKINEN = new Customer(
+            2, "Jarno", "Mäkinen", "jarno@example.com", "Finland", CustomerStatus.PENDING);
+    private static final Customer JOSEPHINE = new Customer(
+            3, "Joséphine", "Engberg", "josephine@example.com", "France", CustomerStatus.CLOSED);
+
+    @Test
+    void emptyFilterMatchesEveryone() {
+        assertTrue(CustomerFilter.EMPTY.matches(AALTONEN));
+        assertTrue(CustomerFilter.EMPTY.matches(MAKINEN));
+    }
+
+    @Test
+    void everyTermMustMatchEitherNameRegardlessOfOrder() {
+        assertTrue(new CustomerFilter("ada aal", Set.of()).matches(AALTONEN));
+        assertTrue(new CustomerFilter("aal ada", Set.of()).matches(AALTONEN));
+        assertFalse(new CustomerFilter("ada virtanen", Set.of()).matches(AALTONEN));
+    }
+
+    @Test
+    void whitespaceAroundAndBetweenTermsIsIgnored() {
+        assertTrue(new CustomerFilter("  ada   aal  ", Set.of()).matches(AALTONEN));
+    }
+
+    @Test
+    void matchingIgnoresCaseAndAccentsBothWays() {
+        assertTrue(new CustomerFilter("makinen", Set.of()).matches(MAKINEN));
+        assertTrue(new CustomerFilter("MAKINEN", Set.of()).matches(MAKINEN));
+        assertTrue(new CustomerFilter("mäkinen", Set.of()).matches(MAKINEN));
+        assertTrue(new CustomerFilter("josephine", Set.of()).matches(JOSEPHINE));
+    }
+
+    @Test
+    void statusFilterWithNothingSelectedMatchesEveryStatus() {
+        assertTrue(new CustomerFilter("", Set.of()).matches(AALTONEN));
+        assertTrue(new CustomerFilter("", Set.of()).matches(MAKINEN));
+    }
+
+    @Test
+    void statusFilterOnlyMatchesSelectedStatuses() {
+        CustomerFilter filter = new CustomerFilter("", Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED));
+        assertTrue(filter.matches(AALTONEN));
+        assertFalse(filter.matches(MAKINEN));
+        assertTrue(filter.matches(JOSEPHINE));
+    }
+
+    @Test
+    void bothFiltersMustMatch() {
+        CustomerFilter filter = new CustomerFilter("aal", Set.of(CustomerStatus.PENDING));
+        assertFalse(filter.matches(AALTONEN), "name matches but status does not");
+    }
+}
